// ---- Trait definition ----
// Traits define shared behavior across types

// ---- A simple trait ----
trait Attackable {
    fn attack(&self, target: &mut impl Damageable);
    fn get_attack_power(&self) -> i32;
}

// ---- Another trait ----
trait Damageable {
    fn take_damage(&mut self, damage: i32);
    fn is_alive(&self) -> bool;
    fn get_health(&self) -> i32;
}

// ---- A trait with a default implementation ----
trait Displayable {
    fn display(&self) -> String;

    // Default implementation
    fn print(&self) {
        println!("{}", self.display());
    }
}

// ---- Implementing traits for a struct ----
struct Player {
    name: String,
    health: i32,
    max_health: i32,
    attack: i32,
    defense: i32,
    level: i32,
}

impl Player {
    fn new(name: &str) -> Player {
        Player {
            name: String::from(name),
            health: 100,
            max_health: 100,
            attack: 15,
            defense: 10,
            level: 1,
        }
    }
}

impl Attackable for Player {
    fn attack(&self, target: &mut impl Damageable) {
        let damage = self.attack + (self.level * 2);
        println!("{} attacks for {} damage!", self.name, damage);
        target.take_damage(damage);
    }

    fn get_attack_power(&self) -> i32 {
        self.attack + (self.level * 2)
    }
}

impl Damageable for Player {
    fn take_damage(&mut self, damage: i32) {
        let actual_damage = damage - self.defense / 2;
        if actual_damage > 0 {
            self.health -= actual_damage;
            if self.health < 0 {
                self.health = 0;
            }
            println!("{} took {} damage! Health: {}", self.name, actual_damage, self.health);
        } else {
            println!("{} blocked the attack!", self.name);
        }
    }

    fn is_alive(&self) -> bool {
        self.health > 0
    }

    fn get_health(&self) -> i32 {
        self.health
    }
}

impl Displayable for Player {
    fn display(&self) -> String {
        format!(
            "Player: {} (Level {}, HP: {}/{})",
            self.name, self.level, self.health, self.max_health
        )
    }
}

// ---- Implementing traits for a different type ----
struct Enemy {
    name: String,
    health: i32,
    max_health: i32,
    attack: i32,
    defense: i32,
    is_boss: bool,
}

impl Enemy {
    fn new(name: &str, is_boss: bool) -> Enemy {
        Enemy {
            name: String::from(name),
            health: if is_boss { 200 } else { 50 },
            max_health: if is_boss { 200 } else { 50 },
            attack: if is_boss { 25 } else { 10 },
            defense: if is_boss { 10 } else { 5 },
            is_boss,
        }
    }
}

impl Attackable for Enemy {
    fn attack(&self, target: &mut impl Damageable) {
        let damage = self.attack;
        println!("{} attacks for {} damage!", self.name, damage);
        target.take_damage(damage);
    }

    fn get_attack_power(&self) -> i32 {
        self.attack
    }
}

impl Damageable for Enemy {
    fn take_damage(&mut self, damage: i32) {
        let actual_damage = damage - self.defense / 2;
        if actual_damage > 0 {
            self.health -= actual_damage;
            if self.health < 0 {
                self.health = 0;
            }
            println!("{} took {} damage! Health: {}", self.name, actual_damage, self.health);
        } else {
            println!("{} blocked the attack!", self.name);
        }
    }

    fn is_alive(&self) -> bool {
        self.health > 0
    }

    fn get_health(&self) -> i32 {
        self.health
    }
}

impl Displayable for Enemy {
    fn display(&self) -> String {
        let boss_str = if self.is_boss { " (BOSS)" } else { "" };
        format!(
            "Enemy: {}{} (HP: {}/{})",
            self.name, boss_str, self.health, self.max_health
        )
    }
}

// ---- Using traits ----
fn main() {
    let mut hero = Player::new("Aragorn");
    let mut goblin = Enemy::new("Goblin", false);
    let mut boss = Enemy::new("Dragon", true);

    // ---- Display ----
    println!("{}", hero.display());
    println!("{}", goblin.display());
    println!("{}", boss.display());

    // ---- Combat ----
    println!("\n--- Combat ---");
    hero.attack(&mut goblin);
    goblin.attack(&mut hero);
    hero.attack(&mut boss);
    boss.attack(&mut hero);

    // ---- Status ----
    println!("\n--- Status ---");
    println!("{}", hero.display());
    println!("{}", goblin.display());
    println!("{}", boss.display());
}

